import json,csv,hashlib,re
from pathlib import Path
b=Path(__file__).resolve().parent
q=list(csv.DictReader((b/'queue.csv').open()));notes=json.loads((b/'lead-decisions-final.json').read_text());g=json.loads((b/'lead-gaia-covariance.json').read_text());cl=json.loads((b/'lead-clocks.json').read_text());inv={x['tic']:x for x in json.loads((b/'lead-current-sector-inventory.json').read_text())};rows=[]
for row in q:
 t=row['tic'];n=notes[t];assert n['verdict']!='PENDING_HELPER';e=json.loads((b/t/'lead-timing.json').read_text());gg=g[t];c=cl.get(t);a=json.loads((b/'lead-alias-covered-windows.json').read_text()).get(t,[])
 lines=[f"# {row['sample_id']}: TIC {t}",f"Full review completion: COMPLETE_BOUNDED. Physical verdict: {n['verdict']}. Association: {n['association']}.",n['reason'],'## Frozen selection and identity',f"Exact queue row: Gaia DR3 {row['gaia_dr3']}, actual nested Gaia G={row['gaia_G']}, selection P={row['gaia_period']}d, stratum={row['sample_stratum']}. Parent fresh-band-next1000; second/batch04 is operational provenance only. No substitutions and no added selection threshold. Historical triage is not a physical verdict. This selected review is not an unbiased discovery-yield denominator.",'identity-audit.json verifies TIC/Gaia identity, nested magnitudes, FITS TIC/sector headers and source SHA256. Parent bulk-results and appointment-results preserve per-target window scores, trial durations, coverage, masks and nonflags for near-threshold revisiting. Historical lead-context flag_events includes recorded dip windows whether or not screening threshold passed.','## Raw flux and measured events','Lead personally inspected representative local and all supplied full-sector plots. Finite TIME, finite positive SAP_FLUX and QUALITY=0 are used. Same-kind events are distinguished from opposite conjunctions before timing. Local linear-baseline symmetric trapezoid fits retain formal conditional timing errors; partial, boundary or unbracketed fits are unusable for precision ephemerides. KSPSAP comparison tests QLP processing with the same photons, not an independent observing occasion.','| Sector | Kind | Trial center BTJD | Depth ppt | Timing usable |','|---|---|---:|---:|---|']
 for x in e:lines.append(f"| {x['sector']} | {x['kind']} | {x.get('center_btjd',0):.6f} | {x.get('depth_ppt',0):.2f} | {x.get('fit_usable',False)} |")
 lines+=['## Recurrence, aliases and coverage']
 if c:lines+=[json.dumps(c,indent=2),'Clock metadata above preserves provisional aliases and approximate periods explicitly; a number is not automatically an adopted ephemeris. lead-alias-covered-windows.json tests divisors2-6, doubling, Gaia and where relevant integer counts across the representative baseline down to5d. All observed same-kind midpoints must agree within0.04d. Both sidebands, >=75% core coverage and no large core gap are required. Local side medians define a sloped baseline. Bin width=min(0.1d,duration/5); >=2 points/bin and >=4 sideband bins give a robust scatter. Clean null criterion is depth+4*binned sideband scatter < half characteristic depth. Native and binned scatter, masks, hashes and ambiguous windows remain saved. This bounded alias comparison is not a blind search or calibrated completeness.','| Trial | Period d | Timing compatible | Covered | Clean nulls |','|---|---:|---|---:|---:|']
 if c:
  for z in a[:6]+a[-2:]:lines.append(f"| {z['label']} | {z['period_d']:.9f} | {z['timing_compatible']} | {z['covered']} | {len(z['nulls'])} |")
 else:lines+=['No free same-kind eclipse period is measured. Single-event conditional Gaia-period coverage is explicitly an assumption, never a measured timing clock. Missing, flagged, drifted or noise-limited windows are not clean nulls.']
 lines+=[f"Current TESScut availability checked {inv[t]['checked_utc']}: {inv[t].get('tesscut_sectors',[])}. Original QLP sectors: {inv[t]['qlp_all_sectors']}. Actual inventory status, request and response hashes are saved. Availability does not guarantee useful photometry.",'## Source attribution and independent reduction',n.get('helper_summary','See HELPER-AUDIT.md and per-target helper receipts for the completed bounded audit. A missing or inconclusive pixel result remains a limitation.'),'Custom TESScut aperture extractions reuse TESS photons; independent sectors are separate observing occasions. Pixel offsets must be assessed against capable Gaia neighbors and background/window sensitivity. No calibrated PRF astrometric uncertainty or dilution correction is implied.','## Source-specific Gaia geometry',f"Gaia P={gg['gaia_period_d']:.9f} +/- {gg['gaia_period_error_d']:.8g}d; e={gg['eccentricity']:.6f}; omega={gg['omega_deg']:.6f}deg; Tp={gg['tp_btjd']:.6f}BTJD; spectroscopic mass function={gg['mass_function_solar']:.7g}solar masses. Fixed-cycle local propagation uses this source's full P,e,omega,Tp correlation submatrix from the SB1 lower triangle P,gamma,K,e,omega,Tp. Edge-on conjunctions are search predictions; consistency neither proves source ownership nor supplies an eclipse timing. Unusable trial-fit geometry remains a proxy, not independent evidence."]
 for z in gg['events']:
  j=min(z['conjunctions'],key=lambda y:abs(y['offset_d']));lines.append(f"S{z['sector']}: nearest nominal conjunction offset={j['offset_d']:.4f}d, local covariance sigma={j['linear_covariance_sigma_d']:.4f}d, trial timing usable={z['fit_usable']}.")
 lines+=['Nonlinear covariance sensitivity is also saved in lead-nonlinear-gaia.json (100000 draws, seed50701, physically valid0<=e<1 and P>0). It aligns conjunction branches before fixed-cycle propagation and reports quantiles and empirical tail fractions. These are Gaia-model consistency diagnostics, not eclipse significance or a full astrophysical posterior. Broad or phase-spanning predictions remain weak compatibility tests.','## Catalogue status','Root-owned ../shared-catalogues/ROOT-CATALOGUE-SEAL.json and target receipts retain the successful scoped VSX/ASAS-SN cones, SIMBAD identities/classifications, Gaia EB/variability tables, Prsa/IJspeert/Kostov vetted tables and additional Kepler/K2/TOI/literature checks. No exact prior EB identity is assigned to these six within the sealed scope. Failed/unavailable queries remain unknown. Scoped nonmatches do not prove exhaustive priority. Physical verdict and catalogue novelty are separate; plausible outcomes are excluded from claims.','## Limitations and next check',n['limitations'],n['next'],'## Evidence and provenance','Target lead-context.json, lead-series.json, lead-timing.json, lead-raw-context.png, lead-fullsectors.png and helper artifacts. Batch identity-audit.json, lead-source-hashes.json, lead-current-sector-inventory.json, lead-clocks.json, lead-alias-covered-windows.json, lead-single-conditional-coverage.json, lead-reduction-comparison.json, lead-gaia-covariance.json, LEAD-AUDIT.md, HELPER-AUDIT.md, SOURCE-MANIFEST.json and SHA256SUMS.json. No ledger or public file was edited.']
 p=b/t/'REPORT.md';p.write_text(re.sub(r'(?m)([|][^\n]*[|])\n\n(?=[|])',r'\1\n','\n\n'.join(lines))+'\n',encoding='utf8')
 adopted=c and n['verdict'] in ['C','P'];rows.append(dict(sample_id=row['sample_id'],tic=t,gaia_dr3=row['gaia_dr3'],physical_verdict=n['verdict'],full_review_completion='COMPLETE_BOUNDED',period_days=f"{c['period_d']:.9f}" if adopted else '',period_interpretation=c['period_note'] if adopted else 'not established; see tested aliases or single-event limits',association=n['association'],limitations=n['limitations'],next_check=n['next'],report=str(p)))
with (b/'RESULTS.csv').open('w',newline='',encoding='utf8') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
print('wrote',len(rows))
